#!/usr/bin/env bash
# MCP ToolGuard v3 installer. The inner code is SHA256 verified before execution.
# Fix: SQLite WAL backup can create/open -shm while main database is opened mode=ro.
# No delete, re-registration, or Nextcloud restart performed during installation.
set -Eeuo pipefail
umask 077
if [ "$(id -u)" -ne 0 ]; then
  echo "Run as root: sudo bash install-mcp-toolguard-v3.sh" >&2
  exit 1
fi
command -v python3 >/dev/null 2>&1 || { echo "Python 3 is required" >&2; exit 1; }
tmp="$(mktemp /tmp/mcp-toolguard-install.XXXXXXXX.py)"
trap 'rm -f -- "$tmp"' EXIT
python3 - "$tmp" <<'PYTHON_PAYLOAD'
import base64, gzip, hashlib, pathlib, sys
b64 = """"""
data = gzip.decompress(base64.b64decode(b64))
if hashlib.sha256(data).hexdigest() != "7af5cd64134404ac7acac07ec20d5b5678ce6b3db44ae92a092564ddd5281cea":
    raise SystemExit("Installer integrity check failed, refusing execution")
p = pathlib.Path(sys.argv[1])
p.write_bytes(data)
p.chmod(0o700)
PYTHON_PAYLOAD
python3 "$tmp" "$@"
